import { useEffect, useMemo, useRef, useState } from "react";
import AMapLoader from "@amap/amap-jsapi-loader";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import {
  fetchAnalysis,
  fetchPublicConfig,
  fetchTraffic,
} from "./api/client";
import "./App.css";

const INTERVAL_OPTIONS = [10, 20, 30];
const DIRECTION_OPTIONS = ["全部方向", "东向西", "西向东", "南向北", "北向南"];
const SEGMENT_ORDER = ["星峰路康田路交叉口", "星峰路交叉口", "星光大道北延申段", "恒福路"];
const DONUT_COLORS = ["#3f8efc", "#28b381", "#f4b93a", "#5d76e8", "#ff7f50"];

function toApiTime(value) {
  return value ? value.replace("T", " ") : undefined;
}

function toInputTime(date) {
  const pad = (v) => `${v}`.padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(
    date.getHours()
  )}:${pad(date.getMinutes())}`;
}

function isTimeRangeValid(startInput, endInput) {
  const start = new Date(startInput);
  const end = new Date(endInput);
  return !Number.isNaN(start.getTime()) && !Number.isNaN(end.getTime()) && end - start >= 3600000;
}

function levelColor(value) {
  if (value >= 60) return "#e14e2d";
  if (value >= 30) return "#f0be3d";
  return "#2db87d";
}

function formatBucket(ts) {
  const date = new Date(ts);
  const h = `${date.getHours()}`.padStart(2, "0");
  const m = `${date.getMinutes()}`.padStart(2, "0");
  return `${h}:${m}`;
}

function buildDonutData(trafficRows, roadName) {
  const grouped = new Map();
  trafficRows
    .filter((item) => (roadName ? item.site_name === roadName : true))
    .forEach((row) => {
      const key = row.approach;
      grouped.set(key, (grouped.get(key) || 0) + row.vehicle_count);
    });
  return [...grouped.entries()].map(([name, value]) => ({ name, value }));
}

function getRoadAverageMap(rows) {
  const grouped = new Map();
  rows.forEach((row) => {
    const current = grouped.get(row.site_name) || { sum: 0, n: 0 };
    current.sum += row.vehicle_count;
    current.n += 1;
    grouped.set(row.site_name, current);
  });
  const result = new Map();
  grouped.forEach((value, key) => {
    result.set(key, value.n ? value.sum / value.n : 0);
  });
  return result;
}

function App() {
  const now = new Date();
  const defaultStart = new Date(now.getTime() - 2 * 3600000);
  const defaultEnd = new Date(defaultStart.getTime() + 3600000);

  const [amapKey, setAmapKey] = useState("");
  const [intersections, setIntersections] = useState([]);
  const [selectedRoad, setSelectedRoad] = useState("");
  const [flowRoad, setFlowRoad] = useState("全部路口平均");
  const [speedRoad, setSpeedRoad] = useState("全部路口平均");
  const [direction, setDirection] = useState("全部方向");

  const [startInput, setStartInput] = useState(toInputTime(defaultStart));
  const [endInput, setEndInput] = useState(toInputTime(defaultEnd));
  const [intervalMinutes, setIntervalMinutes] = useState(10);
  const [applied, setApplied] = useState({
    start: toInputTime(defaultStart),
    end: toInputTime(defaultEnd),
    interval: 10,
    direction: "全部方向",
  });

  const [flowData, setFlowData] = useState([]);
  const [speedData, setSpeedData] = useState([]);
  const [rawTrafficRows, setRawTrafficRows] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const mapContainerRef = useRef(null);
  const mapRef = useRef(null);
  const AMapRef = useRef(null);
  const markerMapRef = useRef(new Map());
  const polylineRef = useRef([]);

  useEffect(() => {
    let alive = true;
    async function loadConfig() {
      try {
        const data = await fetchPublicConfig();
        if (!alive) return;
        setAmapKey(data.amap_api_key);
        const usable = data.intersections.filter((item) => item.longitude || item.latitude);
        setIntersections(usable);
        if (usable.length) {
          setSelectedRoad(usable[0].site_name);
        }
      } catch (err) {
        if (!alive) return;
        setError(`初始化失败：${err.message}`);
      }
    }
    loadConfig();
    return () => {
      alive = false;
    };
  }, []);

  useEffect(() => {
    if (!amapKey || !mapContainerRef.current || !intersections.length) return undefined;
    let destroyed = false;

    async function initMap() {
      const AMap = await AMapLoader.load({
        key: amapKey,
        version: "2.0",
        plugins: ["AMap.Scale", "AMap.ToolBar"],
      });
      if (destroyed) return;
      AMapRef.current = AMap;

      const center = [intersections[0].longitude, intersections[0].latitude];
      const map = new AMap.Map(mapContainerRef.current, {
        center,
        zoom: 15,
        viewMode: "2D",
      });
      map.addControl(new AMap.Scale());
      map.addControl(new AMap.ToolBar({ position: "LB" }));
      mapRef.current = map;

      const markerMap = new Map();
      intersections.forEach((site) => {
        const marker = new AMap.Marker({
          position: [site.longitude, site.latitude],
          title: site.site_name,
          label: {
            direction: "top",
            content: `<div class="amap-label">${site.site_name}</div>`,
          },
        });
        marker.on("click", () => setSelectedRoad(site.site_name));
        marker.setMap(map);
        markerMap.set(site.site_name, marker);
      });
      markerMapRef.current = markerMap;
    }
    initMap();

    return () => {
      destroyed = true;
      if (mapRef.current) {
        mapRef.current.destroy();
        mapRef.current = null;
      }
      markerMapRef.current = new Map();
      polylineRef.current = [];
    };
  }, [amapKey, intersections]);

  useEffect(() => {
    if (!mapRef.current || !selectedRoad) return;
    const target = intersections.find((item) => item.site_name === selectedRoad);
    if (target) {
      mapRef.current.setCenter([target.longitude, target.latitude]);
    }
  }, [selectedRoad, intersections]);

  useEffect(() => {
    if (!applied.start || !applied.end) return;
    let active = true;
    async function loadData() {
      try {
        setLoading(true);
        setError("");

        const commonParams = {
          start_time: toApiTime(applied.start),
          end_time: toApiTime(applied.end),
          interval_minutes: applied.interval,
          direction: applied.direction === "全部方向" ? undefined : applied.direction,
        };

        const [flowResp, speedResp, trafficResp] = await Promise.all([
          fetchAnalysis({
            ...commonParams,
            road_name: flowRoad === "全部路口平均" ? undefined : flowRoad,
          }),
          fetchAnalysis({
            ...commonParams,
            road_name: speedRoad === "全部路口平均" ? undefined : speedRoad,
          }),
          fetchTraffic({
            start_time: commonParams.start_time,
            end_time: commonParams.end_time,
            direction: commonParams.direction,
            limit: 5000,
          }),
        ]);

        if (!active) return;
        setFlowData((flowResp || []).map((item) => ({ ...item, bucketLabel: formatBucket(item.bucket_start) })));
        setSpeedData((speedResp || []).map((item) => ({ ...item, bucketLabel: formatBucket(item.bucket_start) })));
        setRawTrafficRows(trafficResp || []);
      } catch (err) {
        if (!active) return;
        setError(`数据加载失败：${err.message}`);
      } finally {
        if (active) setLoading(false);
      }
    }
    loadData();
    return () => {
      active = false;
    };
  }, [applied, flowRoad, speedRoad]);

  const roadOptions = useMemo(() => ["全部路口平均", ...intersections.map((item) => item.site_name)], [intersections]);
  const selectedRoadInfo = intersections.find((item) => item.site_name === selectedRoad);
  const donutData = useMemo(() => buildDonutData(rawTrafficRows, selectedRoad), [rawTrafficRows, selectedRoad]);
  const roadAvgMap = useMemo(() => getRoadAverageMap(rawTrafficRows), [rawTrafficRows]);

  useEffect(() => {
    if (!mapRef.current || !AMapRef.current || intersections.length < 2) return;
    polylineRef.current.forEach((item) => item.setMap(null));
    polylineRef.current = [];

    const orderedPoints = SEGMENT_ORDER
      .map((name) => intersections.find((item) => item.site_name === name))
      .filter(Boolean);

    for (let i = 0; i < orderedPoints.length - 1; i += 1) {
      const from = orderedPoints[i];
      const to = orderedPoints[i + 1];
      const val = ((roadAvgMap.get(from.site_name) || 0) + (roadAvgMap.get(to.site_name) || 0)) / 2;
      const line = new AMapRef.current.Polyline({
        path: [
          [from.longitude, from.latitude],
          [to.longitude, to.latitude],
        ],
        strokeColor: levelColor(val),
        strokeWeight: 8,
        strokeOpacity: 0.9,
        lineCap: "round",
      });
      line.setMap(mapRef.current);
      polylineRef.current.push(line);
    }
  }, [intersections, roadAvgMap]);

  const detailStats = useMemo(() => {
    const rows = rawTrafficRows.filter((item) => item.site_name === selectedRoad);
    if (!rows.length) return { count: 0, speed: 0 };
    const count = rows.reduce((sum, item) => sum + item.vehicle_count, 0) / rows.length;
    const speed = rows.reduce((sum, item) => sum + item.avg_speed, 0) / rows.length;
    return { count: Math.round(count), speed: Number(speed.toFixed(1)) };
  }, [rawTrafficRows, selectedRoad]);

  function handleApplyTime() {
    if (!isTimeRangeValid(startInput, endInput)) {
      setError("结束时间必须至少比起始时间晚 1 小时。");
      return;
    }
    setApplied({
      start: startInput,
      end: endInput,
      interval: intervalMinutes,
      direction,
    });
  }

  return (
    <div className="app-shell">
      <div className="main-layout">
        <section className="left-map-panel">
          <div className="panel-title">实时流量地图</div>

          <div className="time-card">
            <label>起始时间</label>
            <input type="datetime-local" value={startInput} onChange={(e) => setStartInput(e.target.value)} />
            <label>结束时间</label>
            <input type="datetime-local" value={endInput} onChange={(e) => setEndInput(e.target.value)} />
            <div className="time-row">
              <select value={intervalMinutes} onChange={(e) => setIntervalMinutes(Number(e.target.value))}>
                {INTERVAL_OPTIONS.map((m) => (
                  <option key={m} value={m}>
                    {m} 分钟粒度
                  </option>
                ))}
              </select>
              <select value={direction} onChange={(e) => setDirection(e.target.value)}>
                {DIRECTION_OPTIONS.map((item) => (
                  <option key={item} value={item}>
                    {item}
                  </option>
                ))}
              </select>
            </div>
            <button type="button" onClick={handleApplyTime}>
              查询
            </button>
          </div>

          <div className="map-frame" ref={mapContainerRef} />

          <div className="road-detail-card">
            <div className="road-head">
              <div>
                <h3>{selectedRoad || "请选择路口"}</h3>
                <p>
                  {applied.start.replace("T", " ")} - {applied.end.replace("T", " ")}
                </p>
              </div>
              <div className="metric">
                <span>当段平均流量</span>
                <strong>{detailStats.count} 辆</strong>
                <small>{detailStats.speed} km/h</small>
              </div>
            </div>
            <div className="road-content">
              <div className="donut-wrap">
                <ResponsiveContainer width="100%" height={180}>
                  <PieChart>
                    <Pie data={donutData} dataKey="value" nameKey="name" innerRadius={45} outerRadius={72}>
                      {donutData.map((item, idx) => (
                        <Cell key={item.name} fill={DONUT_COLORS[idx % DONUT_COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
              </div>
              <div className="legend-list">
                {donutData.map((item, idx) => (
                  <div key={item.name} className="legend-item">
                    <span className="dot" style={{ backgroundColor: DONUT_COLORS[idx % DONUT_COLORS.length] }} />
                    <span>{item.name}</span>
                    <strong>{item.value}</strong>
                  </div>
                ))}
              </div>
            </div>
            {selectedRoadInfo ? (
              <div className="coord">
                坐标：{selectedRoadInfo.longitude.toFixed(6)}, {selectedRoadInfo.latitude.toFixed(6)}
              </div>
            ) : null}
          </div>
        </section>

        <aside className="right-panel">
          <section className="section-block">
            <h2>数据分析展示</h2>
            <div className="chart-card">
              <div className="chart-head">
                <h3>车流量柱状图</h3>
                <select value={flowRoad} onChange={(e) => setFlowRoad(e.target.value)}>
                  {roadOptions.map((name) => (
                    <option key={name} value={name}>
                      {name}
                    </option>
                  ))}
                </select>
              </div>
              <ResponsiveContainer width="100%" height={260}>
                <BarChart data={flowData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="bucketLabel" />
                  <YAxis />
                  <Tooltip />
                  <Bar dataKey="vehicle_count" fill="#2f86ff" />
                </BarChart>
              </ResponsiveContainer>
            </div>

            <div className="chart-card">
              <div className="chart-head">
                <h3>车速柱状图</h3>
                <select value={speedRoad} onChange={(e) => setSpeedRoad(e.target.value)}>
                  {roadOptions.map((name) => (
                    <option key={name} value={name}>
                      {name}
                    </option>
                  ))}
                </select>
              </div>
              <ResponsiveContainer width="100%" height={260}>
                <BarChart data={speedData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="bucketLabel" />
                  <YAxis />
                  <Tooltip />
                  <Bar dataKey="avg_speed" fill="#22b88f" />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </section>

          <section className="section-block">
            <h2>预测</h2>
            <div className="dev-card">开发中</div>
          </section>
        </aside>
      </div>

      {loading ? <div className="floating-tip">数据更新中...</div> : null}
      {error ? <div className="floating-error">{error}</div> : null}
    </div>
  );
}

export default App;
